    private import Parts::Part;
    private import StandardViewDefinitions::*;

    package '用例定义' {
        doc /* 电动汽车系统用例定义 */

        use case '电动汽车行驶' : UseCase {
            doc /* 电动汽车行驶顶层用例 */
            subject '电动汽车系统' : Part;
            actor '驾驶员';
            actor '充电站';
            actor '道路设施';

            use case '常规行驶' : UseCase {
                doc /* 常规行驶子用例 */
                subject '电动汽车系统' : Part;
                actor '驾驶员';
            }

            use case '能量回收' : UseCase {
                doc /* 能量回收子用例 */
                subject '电动汽车系统' : Part;
                actor '驾驶员';
            }

            use case '充电管理' : UseCase {
                doc /* 充电管理子用例 */
                subject '电动汽车系统' : Part;
                actor '充电站';
            }
        }

        use case '高速行驶' : UseCase :> '电动汽车行驶' {
            doc /* 高速行驶特化用例:继承顶层用例的主体与参与方 */
        }
    }

    package '视图' {
        doc /* 用例视图定义 */

        view '用例总览' : GeneralView {
            doc /* 电动汽车系统用例视图 */

            expose '电动汽车用例'::'用例定义'::'电动汽车行驶';
            expose '电动汽车用例'::'用例定义'::'高速行驶';
        }
    }
}
```

