            accept '点火指令' : Item via '点火指令口'
            do send new Item() to '控制器'
            then '就绪';

        transition '就绪到行驶'
            first '就绪'
            accept '行驶指令' : Item
            if '电池电量' >= 0.2
            do send new Item() to '控制器'
            then '行驶';

